import ast, glob, os
root='tally/reports'
mods={}
for f in glob.glob(root+'/**/*.py',recursive=True):
    m=os.path.relpath(f,'tally').replace('/','.')[:-3]
    isinit=m.endswith('.__init__'); m=m[:-9] if isinit else m
    mods[m]=(f,isinit)
def layer(m):
    p=m.split('.')
    if len(p)==2: return 6
    top=p[2]
    return {'errors':0,'tables':0,'state':0,'system':0,'formatting':1,'model':1,'loading':2,'aggregate':3,'renderers':4,'cli':5}[top]
g={}
for m,(f,isinit) in mods.items():
    pkg=m if isinit else m.rsplit('.',1)[0]
    deps=set()
    for n in ast.walk(ast.parse(open(f).read())):
        if isinstance(n,ast.ImportFrom):
            if n.level:
                parts=pkg.split('.'); base='.'.join(parts[:len(parts)-(n.level-1)])
                full=base+('.'+n.module if n.module else '')
            else: full=n.module
            if not full.startswith('tally'): continue
            for a in n.names:
                c=full+'.'+a.name
                deps.add(c if c in mods else full)
        elif isinstance(n,ast.Import):
            for a in n.names:
                if a.name.startswith('tally'): deps.add(a.name)
    g[m]=deps
for m,d in g.items():
    for x in d:
        assert x in mods,(m,x)
        if layer(x)>layer(m): print('LAYER',m,x)
        if not x.startswith('tally.reports'): print('EXT',m,x)
# cycles
state={}
def dfs(u,st):
    state[u]=1
    for v in g[u]:
        if v==u: print('self',u)
        if state.get(v)==1: print('CYCLE',u,v)
        elif v not in state: dfs(v,st)
    state[u]=2
for m in g:
    if m not in state: dfs(m,[])
print('done')
